import React from 'react';
import styled from 'styled-components';
import EstimateRenderer from './EstimateRenderer';

const MessageWrapper = styled.div`
  display: flex;
  gap: 15px;
  padding: 12px 0;
  max-width: 800px;
`;

const ProfileImage = styled.img`
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
`;

const ContentWrapper = styled.div`
  flex: 1;
`;

const Header = styled.div`
  display: flex;
  gap: 8px;
  margin-bottom: 4px;

  h2 {
    font-size: 18px;
    font-weight: 500;
    line-height: 160%;
    margin: 4px 0 4px 0;
    color: ${({ theme }) => theme.text};
  }
`;

const MessageContent = styled.div`
  font-size: 14px;
  line-height: 160%;
  color: ${({ theme }) => theme.text};
  white-space: pre-wrap;

  p {
    margin: 0;
  }
`;

interface ShareAiResponseMessageProps {
  content: string;
}

const ShareAiResponseMessage: React.FC<ShareAiResponseMessageProps> = ({ content }) => {
  const isEstimateMessage = (content: string) => {
    return content.includes('<script type="application/json" id="invoiceData">');
  };

  const renderContent = () => {
    if (isEstimateMessage(content)) {
      return <EstimateRenderer content={content} />;
    }

    // 일반 텍스트 메시지인 경우 <script> 태그 제거
    const cleanContent = content.replace(/<script[^>]*>[\s\S]*?<\/script>/g, '').trim();

    if (cleanContent) {
      return <p>{cleanContent}</p>;
    }

    return null;
  };

  return (
    <MessageWrapper>
      <ContentWrapper>
        <Header>
          <ProfileImage src="/ai-estimate/pretty.png" alt="AI 컨설턴트" />
          <h2>AI 컨설턴트</h2>
        </Header>
        <MessageContent>
          {renderContent()}
        </MessageContent>
      </ContentWrapper>
    </MessageWrapper>
  );
};

export default ShareAiResponseMessage;
